package com.retro.launcher;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.AudioManager;import android.view.*;
final class SoundPanel extends View {
 final MainActivity a;final AudioManager audio;final boolean volume;final Paint p=new Paint(3);int row;float scale=1;
 final int[] streams={AudioManager.STREAM_RING,AudioManager.STREAM_MUSIC,AudioManager.STREAM_ALARM};final String[] labels={"Ringtone","Media","Alarm"};
 SoundPanel(MainActivity owner,boolean controls){super(owner);a=owner;volume=controls;audio=(AudioManager)a.getSystemService(Context.AUDIO_SERVICE);setFocusableInTouchMode(true);requestFocus();setContentDescription(controls?"Volume. Up and Down select; Left and Right adjust; Clear closes.":"Sound mode");}
 static void glyph(Canvas c,float x,float y,float size,int mode){Paint b=new Paint();float u=size/16;int color=mode==2?0xff77efb3:mode==1?0xffffd76a:0xffb4dfff;b.setColor(color);String[] speaker={"0000000100000000","0000001100000000","0000011100000000","0011111100000000","0011111100000000","0011111100000000","0011111100000000","0011111100000000","0011111100000000","0011111100000000","0000011100000000","0000001100000000","0000000100000000"};if(mode==1){for(int yy=3;yy<13;yy++)for(int xx=5;xx<11;xx++)if(yy==3||yy==12||xx==5||xx==10)c.drawRect(x+xx*u,y+yy*u,x+(xx+1)*u,y+(yy+1)*u,b);for(int yy=4;yy<12;yy++){int xx=yy%4<2?2:3;c.drawRect(x+xx*u,y+yy*u,x+(xx+1)*u,y+(yy+1)*u,b);c.drawRect(x+(15-xx)*u,y+yy*u,x+(16-xx)*u,y+(yy+1)*u,b);}return;}for(int yy=0;yy<speaker.length;yy++)for(int xx=0;xx<16;xx++)if(speaker[yy].charAt(xx)=='1')c.drawRect(x+xx*u,y+(yy+1)*u,x+(xx+1)*u,y+(yy+2)*u,b);if(mode==2){for(int yy=4;yy<=11;yy++){int xx=yy<6||yy>9?12:14;c.drawRect(x+xx*u,y+yy*u,x+(xx+1)*u,y+(yy+1)*u,b);}c.drawRect(x+10*u,y+6*u,x+11*u,y+10*u,b);}else{b.setColor(0xffff7d89);for(int k=0;k<5;k++){c.drawRect(x+(10+k)*u,y+(6+k)*u,x+(11+k)*u,y+(7+k)*u,b);c.drawRect(x+(14-k)*u,y+(6+k)*u,x+(15-k)*u,y+(7+k)*u,b);}}}
 protected void onMeasure(int ws,int hs){int w=resolveSize((int)(300*getResources().getDisplayMetrics().density),ws);setMeasuredDimension(w,resolveSize((int)(w*(volume?250:118)/240f),hs));}
 void text(Canvas c,String value,float x,float y,float size,int color){p.setShader(null);p.setColor(color);p.setTypeface(Typeface.create("monospace",Typeface.BOLD));p.setTextSize(size);c.drawText(value,x,y,p);}
 protected void onDraw(Canvas canvas){scale=getWidth()/240f;Canvas c=canvas;c.save();c.scale(scale,scale);float h=volume?250:118;p.setShader(new LinearGradient(0,0,0,h,new int[]{0xff6f8ba8,0xff102943,0xff051323},null,Shader.TileMode.CLAMP));c.drawRoundRect(1,1,239,h-1,6,6,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(0xff58dcff);c.drawRoundRect(2,2,238,h-2,5,5,p);p.setStyle(Paint.Style.FILL);int mode=audio.getRingerMode();glyph(c,13,13,30,mode);text(c,volume?"VOLUME":mode==2?"SOUND":mode==1?"VIBRATE":"SILENT",52,35,16,0xffedfbff);if(!volume){text(c,"Sound mode changed",22,87,11,0xffb6cde2);c.restore();return;}for(int i=0;i<3;i++){float y=58+i*49;if(i==row){p.setColor(0xff1a5078);c.drawRoundRect(9,y,231,y+44,3,3,p);}text(c,labels[i],16,y+14,11,0xffe1f4ff);int max=audio.getStreamMaxVolume(streams[i]),current=audio.getStreamVolume(streams[i]);for(int k=0;k<12;k++){p.setColor(k<(int)Math.ceil(current*12f/Math.max(1,max))?0xff39ccff:0xff24394e);c.drawRect(18+k*14,y+24,28+k*14,y+34,p);}text(c,current+"/"+max,191,y+32,8,0xffedfbff);}text(c,"◀ / ▶ Adjust",16,222,10,0xffb4d2e8);text(c,"Close",174,237,11,0xffedfbff);c.restore();}
 void adjust(int delta){try{int stream=streams[row],next=Math.max(0,Math.min(audio.getStreamMaxVolume(stream),audio.getStreamVolume(stream)+delta));audio.setStreamVolume(stream,next,0);invalidate();a.view.invalidate();}catch(SecurityException e){a.features.toast("Android requires sound-mode access for that change");}}
 public boolean onKeyDown(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_DPAD_UP){row=(row+2)%3;invalidate();return true;}if(key==KeyEvent.KEYCODE_DPAD_DOWN){row=(row+1)%3;invalidate();return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_VOLUME_DOWN){adjust(-1);return true;}if(key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_VOLUME_UP){adjust(1);return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||key==KeyEvent.KEYCODE_BACK){if(a.features.dialog!=null)a.features.dialog.dismiss();return true;}return super.onKeyDown(key,event);}
 public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()!=android.view.MotionEvent.ACTION_UP)return true;float x=e.getX()/scale,y=e.getY()/scale;if(!volume||y>210){if(a.features.dialog!=null)a.features.dialog.dismiss();}else if(y>=58&&y<205){row=Math.min(2,(int)((y-58)/49));adjust(x<120?-1:1);}performClick();return true;}public boolean performClick(){super.performClick();return true;}
 static void show(MainActivity a,boolean controls){if(a.orbEffect.active())a.orbEffect.cancel();SoundPanel panel=new SoundPanel(a,controls);AlertDialog dialog=new AlertDialog.Builder(a).create();dialog.setView(panel,0,0,0,0);a.features.show(dialog);dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));panel.requestFocus();if(!controls)a.handler.postDelayed(()->{if(a.features.dialog==dialog)dialog.dismiss();},850);}
}
